/*
 * Tidepool design tokens.
 * Source: Figma variables via the Figma MCP (get_variable_defs), Light mode.
 * https://www.figma.com/design/b0LpOCBsaRgo8lUqbkQNaY
 */

:root {
  color-scheme: light;

  /* Color: text & surface */
  --text-primary: #1b2433;
  --surface-page: #ffffff;

  /* Color: button */
  --button-background: #1f5fd6;
  --button-background-hover: #1849a8;
  --button-text: #ffffff;

  /* Color: chip */
  --chip-background: #e8eef9;
  --chip-text: #1b2433;

  /* Color: field */
  --field-border: #7d8799;
  --field-border-error: #c4231b;

  /* Spacing */
  --gap-s: 4px;
  --padding-xs: 4px;
  --padding-s: 8px;
  --padding-m: 12px;

  /* Radii */
  --radii-field: 6px;
  --radii-button: 8px;
  --radii-chip: 16px;

  /* Stroke */
  --stroke-default: 1px;

  /* Typography (Figma text styles "m" and "s") */
  --font-family: "Inter", sans-serif;
  --font-m: 500 14px/20px var(--font-family);
  --font-m-letter-spacing: 0;
  --font-s: 500 12px/16px var(--font-family);
  --font-s-letter-spacing: 0;
}

/*
 * Dark mode.
 * TODO: the Figma MCP only exposes the Light mode of each variable, so no dark
 * values were available. Fill these in from Figma's Dark mode and uncomment.
 * Non-color tokens (spacing, radii, stroke, typography) don't change per mode.
 */
