/*
 * Tidepool design tokens
 * https://www.figma.com/design/b0LpOCBsaRgo8lUqbkQNaY
 *
 * Values come from the Figma MCP's get_variable_defs output for the Settings,
 * Button, Chip, Field and Tag nodes (figma-mcp/*.md). Variable names match Figma's.
 */

:root {
  color-scheme: light;

  /* Colour: Light mode */
  --surface-page: #ffffff;
  --text-primary: #1b2433;

  --button-background: #1f5fd6;
  --button-background-hover: #1849a8;
  --button-text: #ffffff;

  --chip-background: #e8eef9;
  --chip-text: #1b2433;

  --field-border: #7d8799;
  --field-border-error: #c4231b;

  /* Spacing (same in every mode) */
  --gap-s: 4px;
  --padding-xs: 4px;
  --padding-s: 8px;
  --padding-m: 12px;

  /* Radii */
  --radii-field: 6px;
  --radii-button: 8px;
  --radii-chip: 16px;

  /* Stroke */
  --stroke-default: 1px;

  /* Typography (Figma text styles "m" and "s") */
  --font-family: "Inter", sans-serif;

  --font-m-size: 14px;
  --font-m-weight: 500;
  --font-m-line-height: 20px;
  --font-m-letter-spacing: 0;

  --font-s-size: 12px;
  --font-s-weight: 500;
  --font-s-line-height: 16px;
  --font-s-letter-spacing: 0;
}

/*
 * Colour: Dark mode
 *
 * TODO: the Figma MCP's design-to-code tools only return each variable's Light
 * value, so the Dark values aren't available yet. Read them from the Figma file's
 * Dark mode (or a capture that reads every mode) and fill in this block. It needs
 * to override every colour token above:
 *   --surface-page, --text-primary,
 *   --button-background, --button-background-hover, --button-text,
 *   --chip-background, --chip-text,
 *   --field-border, --field-border-error
 *
 * :root[data-theme="dark"] {
 *   color-scheme: dark;
 * }
 *
 * @media (prefers-color-scheme: dark) {
 *   :root:not([data-theme="light"]) {
 *     color-scheme: dark;
 *   }
 * }
 */

/*
 * Tidepool design tokens
 * Source: Figma file b0LpOCBsaRgo8lUqbkQNaY, get_variable_defs for the Settings
 * screen (3:28) and the Button (3:8), Chip (3:16), Field (3:21) and Tag (3:26)
 * components.
 *
 * Only the Light mode came through the Figma MCP. Dark values are missing, so
 * the dark blocks below hold commented-out placeholders: until they are filled
 * in from Figma, dark mode falls back to the Light values.
 */

:root {
  color-scheme: light;

  /* Colour: surface and text */
  --surface-page: #ffffff;
  --text-primary: #1b2433;

  /* Colour: button */
  --button-background: #1f5fd6;
  --button-background-hover: #1849a8;
  --button-text: #ffffff;

  /* Colour: chip */
  --chip-background: #e8eef9;
  --chip-text: #1b2433;

  /* Colour: field */
  --field-border: #7d8799;
  --field-border-error: #c4231b;

  /* Spacing */
  --gap-s: 4px;
  --padding-xs: 4px;
  --padding-s: 8px;
  --padding-m: 12px;

  /* Radii */
  --radii-field: 6px;
  --radii-button: 8px;
  --radii-chip: 16px;

  /* Stroke */
  --stroke-default: 1px;

  /* Typography (Figma text styles "m" and "s") */
  --font-family: "Inter", sans-serif;
  --font-m-size: 14px;
  --font-m-weight: 500;
  --font-m-line-height: 20px;
  --font-m-letter-spacing: 0;
  --font-s-size: 12px;
  --font-s-weight: 500;
  --font-s-line-height: 16px;
  --font-s-letter-spacing: 0;
}

/*
 * Dark mode: explicit opt-in via data-theme, plus the OS preference when no
 * theme is set. Only colour variables change between modes.
 */
[data-theme="dark"] {
  /* TODO: Dark values from Figma (not returned by the Figma MCP)
  --surface-page: ;
  --text-primary: ;
  --button-background: ;
  --button-background-hover: ;
  --button-text: ;
  --chip-background: ;
  --chip-text: ;
  --field-border: ;
  --field-border-error: ;
  color-scheme: dark;
  */
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    /* TODO: same Dark values as [data-theme="dark"] above */
  }
}

