import "./Chip.css";

// Tidepool chip (Figma node 3:16): a filter people switch on and off.
export function Chip({
  label = "Filter",
  size = "M",
  icon = false,
  selected = false,
  onClick,
  className,
  ...rest
}) {
  const classes = ["chip", size === "L" && "chip--l", className]
    .filter(Boolean)
    .join(" ");

  return (
    <button
      type="button"
      className={classes}
      aria-pressed={selected}
      onClick={onClick}
      {...rest}
    >
      {icon && <span className="chip__icon" aria-hidden="true" />}
      {label}
    </button>
  );
}

export default Chip;

