import "./Chip.css";

/**
 * Tidepool chip (Figma node 3:16): a filter people switch on and off.
 *
 * Pass `selected` to make it a toggle; it is exposed as aria-pressed.
 */
export function Chip({
  label = "Filter",
  size = "M",
  icon = false,
  selected,
  className,
  type = "button",
  ...rest
}) {
  const classes = ["chip", size === "L" ? "chip--l" : "chip--m", className]
    .filter(Boolean)
    .join(" ");

  return (
    <button type={type} className={classes} aria-pressed={selected} {...rest}>
      {icon && <span className="chip__icon" aria-hidden="true" />}
      <span className="chip__label">{label}</span>
    </button>
  );
}

export default Chip;

