import "./Field.css";

/**
 * Tidepool "field" (Figma node 3:21): a one-line text input.
 * `state` mirrors the Figma variant ("Default" | "Error"); other props go to the <input>.
 */
export function Field({ state = "Default", className, type = "text", ...props }) {
  const isError = state === "Error";
  const classes = ["field", isError && "field--error", className].filter(Boolean).join(" ");
  return <input type={type} className={classes} aria-invalid={isError || undefined} {...props} />;
}

export default Field;

