export function Tag({ label = "New", tone = "neutral", className, ...rest }) {
  const classes = ["tag", tone === "positive" && "tag--positive", className]
    .filter(Boolean)
    .join(" ");

  return (
    <span className={classes} {...rest}>
      <span className="tag__label">{label}</span>
    </span>
  );
}

export default Tag;

