import { Chip } from '../components/Chip';
import { Field } from '../components/Field';
import { Tag } from '../components/Tag';

export function Settings() {
  const [filters, setFilters] = useState({ plain: false, icon: false });
  const toggle = (key) => setFilters((f) => ({ ...f, [key]: !f[key] }));

  return (
    <main className="settings">
      <h1 className="settings__title">Settings</h1>
      <Field value="Ada" label="Name" />
      <div className="settings__filters">
        <Chip Label="Filter" pressed={filters.plain} onClick={() => toggle('plain')} />
        <Chip Label="Filter" Size="L" Icon pressed={filters.icon} onClick={() => toggle('icon')} />
        <Tag Label="New" Tone="Positive" />
      </div>
      <Button Label="Save" />
    </main>
  );
}

